// TC-098 | req_ids: REQ-017 | level: integration | type: hybrid | model: shopcheck@25673b2
// Data integrity: line-item price captured at placement is immune to later catalog price change
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-098: Data integrity: line-item price captured at placement is immune to later catalog price change', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('standard_user');
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const inStock = products.filter((p) => p.stock >= 1).slice(0, 2);
  expect(inStock.length).toBe(2);
  const res = await api.post('/api/orders', { data: { items: inStock.map((p) => ({ product_id: p.id, quantity: 1 })) } });
  // Expected (full): Order placed with captured price X; Captured price recorded
  const orderId = (await res.json()).id;
  await loginAs('admin');
  const products2: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const seededProduct = products2[0];  // first active seeded product
  await api.put(`/api/products/${seededProduct.id}`, { data: { name: 'Generated product TC-098', description: 'created by TC-098', price: 123.45, stock: 10, is_active: true } });
  // Expected: Product price updated to Y
  await api.get(`/api/orders/${orderId}`);
  // Expected: Line item still shows price X, unaffected by Y
});
